local CoWait = CS.Engine.Lib.CoWait
local cardConfMgr = CardConfMgr:GetInstance()
local KTool = CS.Engine.Lib.KTool
local Text = CS.UnityEngine.UI.Text
local Button = CS.UnityEngine.UI.Button
local KCookie = CS.Engine.Lib.KCookie
local UIModule = CS.Engine.UI.UIModule
local Image = CS.UnityEngine.UI.Image
------------ import ------------
local UIBattlingTools = import("Game.UI.UIBattling.UIBattlingTools")

---@class UIFightChooseCardsSkillInfoNode                         
local UIFightChooseCardsSkillInfoNode = Class("UIFightChooseCardsSkillInfoNode")

function UIFightChooseCardsSkillInfoNode:__init()
    self._data = nil
    self._cb = nil
end

function UIFightChooseCardsSkillInfoNode:__delete()
    self._data = nil
    self._cb = nil
end

function UIFightChooseCardsSkillInfoNode:Awake()
    CfUtils.FillText(self.LV, localize("LV"))
    SetButtonAction(self.SkillIcon, Bind(self, self.OnBtnSkillDesc))
end

function UIFightChooseCardsSkillInfoNode:Refresh(data, cb)
    if not data then
        return
    end
    self._data = data 
    self._cb = cb

    ---@type SkillCardVo
    local skillCardVo = UIBattlingTools.GetSkillCardInfoByTwoParam(data.skillId)
    if not skillCardVo then
        return
    end
    CfUtils.FillText(self.SkillName, skillCardVo.skillName)
    CfUtils.FillText(self.LVNum, data.skillLevel)

    local listSkillCardImgPath = skillCardVo.skillIconPath
    local skillCardImgPath = listSkillCardImgPath[data.skillLevel] or listSkillCardImgPath[1]
    CfUtils.FillImage(self.SkillIcon, skillCardImgPath, true)

    local label = skillCardVo.label
    local showLabel = UICommonUtils:GetSkillShowLabelWithStar(label, data.skillLevel)
    local path, color = UICommonUtils:GetCardSkillAttrIcon(checkInt(showLabel), data.attributeType)
    CfUtils.FillImage(self.SkillType, path, true, nil, nil, color)
    CfUtils.FillText(self.typeName, UICommonUtils:GetSkillLabelNameByType(checkInt(showLabel)))

    self:FillAttrColor(data.attributeType, checkInt(showLabel))

    local color = self._data.isFinal and "ffffff" or Constants.SkillCardColor[string.format("%d_%d",checkNumber(data.attributeType), 1)]
    local pathFramePart = CS.System.IO.Path.GetFileNameWithoutExtension(self._data.isFinal and Constants.SkillCardFrame.SP or Constants.SkillCardFrame.Common)
    local pathFrame = string.format("UIAtlas/Cultivate/AttributeIcon/%s.png", pathFramePart) 
    CfUtils.FillImage(self.skillInfo.transform:Find("SkillBg"), pathFrame)
    self.skillInfo.transform:Find("SkillBg"):GetComponent(typeof(Image)).color = CS.Engine.Lib.XLuaUtils.HexToColor(color)

    KTool.SetActive(self.LVNum, not checkBool(data.isFinal))
    KTool.SetActive(self.LV, not checkBool(data.isFinal))
end

function UIFightChooseCardsSkillInfoNode:FillAttrColor(cardAttr, skillType)
    cardAttr = checkNumber(cardAttr)
    skillType = checkNumber(skillType)

    local color = Color.New(148/255, 148/255, 148/255, 1)  --白
    --进攻型的才改颜色
    if skillType == Constants.SkillLabel.Attack then
        if cardAttr == 1 then       --红
            color = Color.New(1, 23/255, 83/255, 1)
        elseif cardAttr == 2 then   --绿
            color = Color.New(56/255, 205/255, 70/255, 1)
        elseif cardAttr == 3 then   --蓝
            color = Color.New(69/255, 115/255, 235/255, 1)
        elseif cardAttr == 4 then   --白
        elseif cardAttr == 5 then   --黑
            color = Color.New(251/255, 189/255, 44/255, 1)
        end
    end

    self.ColourSkill.color = color
end

--技能介绍
function UIFightChooseCardsSkillInfoNode:OnBtnSkillDesc()
    if self._cb then
        self._cb()
    end
end

function UIFightChooseCardsSkillInfoNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFightChooseCardsSkillInfoNode





